import json
# Look at the team members of PersonalizeForce product
with open('DATA/products/PersonalizeForce.json') as f:
    data = json.load(f)

# Gather all user IDs that appear in the data
all_user_ids = set()
for msg in data['slack']:
    user = msg.get('Message', {}).get('User', {}).get('userId', '')
    if user:
        all_user_ids.add(user)
    for r in msg.get('ThreadReplies', []):
        ru = r.get('Message', {}).get('User', {}).get('userId', '')
        if ru:
            all_user_ids.add(ru)

# Print all user IDs (and their channel participation)
user_channels = {}
for msg in data['slack']:
    ch = msg.get('Channel', {}).get('name', '')
    user = msg.get('Message', {}).get('User', {}).get('userId', '')
    if user:
        user_channels.setdefault(user, set()).add(ch)
    for r in msg.get('ThreadReplies', []):
        ru = r.get('Message', {}).get('User', {}).get('userId', '')
        ch_r = r.get('Channel', {}).get('name', '')
        if ru:
            user_channels.setdefault(ru, set()).add(ch_r)

# Print in sorted order
for u in sorted(all_user_ids):
    channels = user_channels.get(u, set())
    print(f"{u}: {channels}")
EOF

